"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import * as Primitive from "@radix-ui/react-dropdown-menu";
import { Check, Circle } from "lucide-react";
import { useEffect, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { GlideHighlight, useHighlightedGlide } from "./glide-highlight";
import { cn } from "./lib/cn";
import "./shared/dropdown-content.css";
import "./dropdown-menu.css";

export const DropdownMenu = Primitive.Root;
export const DropdownMenuTrigger = Primitive.Trigger;
export const DropdownMenuGroup = Primitive.Group;
export const DropdownMenuRadioGroup = Primitive.RadioGroup;

export function DropdownMenuContent({
  className,
  sideOffset = 8,
  collisionPadding = 16,
  children,
  ...props
}: ComponentProps<typeof Primitive.Content>) {
  const [content, setContent] = useState<HTMLDivElement | null>(null);
  const box = useHighlightedGlide(content);
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={setContent}
        data-slot="dropdown-content"
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "relative z-50 min-w-56 max-w-[calc(100vw-2rem)] max-h-[var(--radix-dropdown-menu-content-available-height)] overflow-y-auto rounded-[14px] border border-border bg-elevated p-1 text-[13px] text-foreground shadow-overlay outline-none",
          className,
        )}
        {...props}
      >
        <GlideHighlight box={box} />
        {children}
      </Primitive.Content>
    </Primitive.Portal>
  );
}

/** Row anatomy shared by every menu: dropdown, menubar and context menus. */
export const menuItemClass =
  "relative z-10 flex min-h-[34px] max-md:min-h-[var(--control-height)] cursor-default select-none items-center gap-2.5 rounded-[10px] px-2.5 text-[13px] font-normal outline-none data-[highlighted]:text-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-45 data-[variant=destructive]:text-destructive [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground data-[variant=destructive]:[&_svg]:text-destructive";

export function DropdownMenuItem({
  className,
  ...props
}: ComponentProps<typeof Primitive.Item>) {
  return (
    <Primitive.Item
      data-slot="dropdown-item"
      className={cn(menuItemClass, className)}
      {...props}
    />
  );
}
export function DropdownMenuCheckboxItem({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.CheckboxItem>) {
  return (
    <Primitive.CheckboxItem
      data-slot="dropdown-item"
      className={cn(menuItemClass, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Primitive.ItemIndicator>
          <Check aria-hidden="true" />
        </Primitive.ItemIndicator>
      </span>
      {children}
    </Primitive.CheckboxItem>
  );
}
export function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.RadioItem>) {
  return (
    <Primitive.RadioItem
      data-slot="dropdown-item"
      className={cn(menuItemClass, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Primitive.ItemIndicator>
          <Circle className="!size-2 fill-current" aria-hidden="true" />
        </Primitive.ItemIndicator>
      </span>
      {children}
    </Primitive.RadioItem>
  );
}
export function DropdownMenuLabel({
  className,
  ...props
}: ComponentProps<typeof Primitive.Label>) {
  return (
    <Primitive.Label
      className={cn(
        "px-2.5 pb-1 pt-2 text-xs font-medium text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}
export function DropdownMenuSeparator({
  className,
  ...props
}: ComponentProps<typeof Primitive.Separator>) {
  return (
    <Primitive.Separator
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}

export function DropdownMenuShortcut({
  className,
  ...props
}: ComponentProps<"span">) {
  return (
    <span
      className={cn(
        "ml-auto pl-4 font-mono text-xs tracking-wide text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

/**
 * A destructive item that asks in place: choosing it turns the row into the
 * question with Cancel and the confirming action, instead of stacking a
 * dialog on the menu. Both answers are menu items, so arrows and Enter work.
 */
export function DropdownMenuConfirmItem({
  label,
  icon,
  question,
  detail,
  confirmLabel = "Delete",
  onConfirm,
}: {
  label: string;
  icon?: ReactNode;
  /** e.g. "Delete 3 files?" */
  question: string;
  /** e.g. "They move to Trash for 30 days." */
  detail?: string;
  confirmLabel?: string;
  onConfirm: () => void;
}) {
  const [asking, setAsking] = useState(false);
  const cancel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (asking) cancel.current?.focus();
  }, [asking]);
  if (!asking) {
    return (
      <DropdownMenuItem
        data-variant="destructive"
        onSelect={(event) => {
          event.preventDefault();
          setAsking(true);
        }}
      >
        {icon}
        {label}
      </DropdownMenuItem>
    );
  }
  return (
    <div data-slot="menu-confirm" role="group" aria-label={question}>
      <p className="px-2.5 pt-2 text-[13px] font-medium text-destructive">{question}</p>
      {detail && <p className="px-2.5 pb-1 text-xs text-muted-foreground">{detail}</p>}
      <DropdownMenuItem
        ref={cancel}
        onSelect={(event) => {
          event.preventDefault();
          setAsking(false);
        }}
      >
        Cancel
      </DropdownMenuItem>
      <DropdownMenuItem data-variant="destructive" onSelect={onConfirm}>
        {icon}
        {confirmLabel}
      </DropdownMenuItem>
    </div>
  );
}

"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { Check, ChevronDown } from "lucide-react";
import { useState, type ReactNode } from "react";
import { Button, type ButtonProps } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuTrigger,
} from "./dropdown-menu";
import * as Primitive from "@radix-ui/react-dropdown-menu";
import "./split-button.css";

export type SplitAction = {
  label: string;
  onSelect: () => void;
  disabled?: boolean;
};

export type SplitOption = {
  value: string;
  label: string;
  /** One line on what this choice does, e.g. "4 commits become one on main". */
  description?: string;
  disabled?: boolean;
};

type Shared = Omit<ButtonProps, "children" | "onClick" | "size"> & {
  menuLabel?: string;
  size?: "sm" | "md" | "lg";
};

type ActionsMode = Shared & {
  /** Alternatives that run immediately from the menu. */
  actions: readonly SplitAction[];
  children: ReactNode;
  onClick?: ButtonProps["onClick"];
  options?: never;
};

type ChoiceMode = Shared & {
  /** Choices; the selected one becomes the button's label. */
  options: readonly SplitOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Runs the selected option. */
  onRun: (value: string) => void;
  /** Small heading above the options, e.g. "Merge method". */
  menuHeading?: string;
  icon?: ReactNode;
  actions?: never;
};

const optionRow =
  "items-start py-2 pl-8 max-md:min-h-[52px] [&_[data-slot=split-check]]:absolute [&_[data-slot=split-check]]:left-2.5 [&_[data-slot=split-check]]:top-2.5";

/**
 * A primary action joined to its close alternatives. In choice mode the
 * chosen option becomes the label, and every option states its consequence.
 */
export function SplitButton(props: ActionsMode | ChoiceMode) {
  const { menuLabel = "More actions", variant = "default", size = "md", disabled } = props;
  const [inner, setInner] = useState(
    props.options ? (props.defaultValue ?? props.options.find((o) => !o.disabled)?.value ?? "") : "",
  );

  const triggerClass = size === "lg" ? "size-11 rounded-l-none" : size === "sm" ? "size-8 rounded-l-none" : "rounded-l-none";

  if (props.options) {
    const { options, value, onValueChange, onRun, menuHeading, icon } = props;
    const current = value ?? inner;
    const selected = options.find((o) => o.value === current) ?? options[0];
    const choose = (next: string) => {
      if (value === undefined) setInner(next);
      onValueChange?.(next);
    };
    return (
      <div data-slot="split-button" className="inline-flex items-stretch gap-px">
        <Button
          variant={variant}
          size={size}
          disabled={disabled}
          className="rounded-r-none"
          onClick={() => onRun(selected.value)}
        >
          {icon}
          {selected.label}
        </Button>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant={variant} size="icon" disabled={disabled} aria-label={menuLabel} className={triggerClass}>
              <ChevronDown data-slot="split-chevron" aria-hidden="true" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-80">
            {menuHeading && <DropdownMenuLabel>{menuHeading}</DropdownMenuLabel>}
            <DropdownMenuRadioGroup value={selected.value} onValueChange={choose}>
              {options.map((option) => (
                <Primitive.RadioItem
                  key={option.value}
                  value={option.value}
                  disabled={option.disabled}
                  data-slot="dropdown-item"
                  className={`relative z-10 flex cursor-default select-none gap-2.5 rounded-[8px] px-2.5 text-[13px] outline-none data-[disabled]:opacity-60 ${optionRow}`}
                >
                  <span data-slot="split-check" className="flex size-4 items-center justify-center">
                    <Primitive.ItemIndicator>
                      <Check className="size-4" aria-hidden="true" />
                    </Primitive.ItemIndicator>
                  </span>
                  <span className="grid gap-0.5">
                    <span className="text-sm font-medium">{option.label}</span>
                    {option.description && (
                      <span className="text-xs text-muted-foreground">{option.description}</span>
                    )}
                  </span>
                </Primitive.RadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    );
  }

  const { actions, children, onClick, ...rest } = props;
  delete (rest as Partial<ActionsMode>).menuLabel;
  delete (rest as Partial<ActionsMode>).variant;
  delete (rest as Partial<ActionsMode>).size;
  return (
    <div data-slot="split-button" className="inline-flex items-stretch gap-px">
      <Button variant={variant} size={size} className="rounded-r-none" onClick={onClick} {...rest}>
        {children}
      </Button>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant={variant} size="icon" disabled={disabled} aria-label={menuLabel} className={triggerClass}>
            <ChevronDown data-slot="split-chevron" aria-hidden="true" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {actions.map((action) => (
            <DropdownMenuItem
              key={action.label}
              disabled={action.disabled}
              onSelect={action.onSelect}
              className="max-md:min-h-[52px]"
            >
              {action.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

/* Shared by button.tsx, confirm-morph.tsx, expanding-button-group.tsx, field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loading-indicator"] {
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loading-indicator"] {
      animation: none;
    }
  }
}

/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--sunken);
    --b-bg-hover: var(--sunken);
    --b-bg-press: var(--sunken);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* Shared by context-menu.tsx, dropdown-menu.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="dropdown-item"] {
    transition:
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out),
      scale var(--duration-fast) var(--ease-out);
  }
  [data-slot="dropdown-item"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
  }
  [data-slot="dropdown-content"] {
    transform-origin: var(--radix-dropdown-menu-content-transform-origin);
  }
  [data-slot="dropdown-content"] [data-slot="glide-highlight"] {
    border-radius: 12px;
    transition:
      transform var(--duration-fast) var(--ease-out),
      width var(--duration-fast) var(--ease-out),
      height var(--duration-fast) var(--ease-out),
      opacity var(--duration-fast) var(--ease-out);
  }
  [data-slot="dropdown-content"][data-state="open"] {
    animation: caliper-dialog-enter var(--duration-normal) var(--ease-settle);
  }
  [data-slot="dropdown-content"][data-state="closed"] {
    animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="dropdown-item"] {
      transition: none;
    }
    [data-slot="dropdown-content"] {
      animation: none;
    }
    /* Preserve the exit name for Radix Presence's completion matcher, including
       a preference changed during exit. No visual motion or unmount timer. */
    [data-slot="dropdown-content"][data-state="closed"] {
      animation: caliper-fade-out var(--duration-instant) var(--ease-in) forwards !important;
    }
  }
}

[data-slot="dropdown-content"] {
  background-color: var(--elevated-glass);
  border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
  backdrop-filter: blur(var(--blur-overlay));
  box-shadow:
    var(--shadow-overlay),
    0 0 40px var(--edge-glow),
    inset 0 1px 0 var(--edge-light);
}
@layer components {
  [data-slot="dropdown-content"][data-variant="glass"] {
    background: var(--elevated-glass);
    -webkit-backdrop-filter: blur(24px) saturate(1.5);
    backdrop-filter: blur(24px) saturate(1.5);
    border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
    box-shadow: var(--shadow-overlay), inset 0 1px 0 var(--edge-light);
    border-radius: 20px;
  }
  /* Moving along the bar swaps menus at once: a closing menu that lingered to fade would see focus leave and dismiss the bar. */
  [data-slot="dropdown-content"][data-menubar][data-state="closed"] { animation: none; }
}

/* dropdown-menu.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="menu-confirm"] {
    margin: 2px 0;
    padding-bottom: 2px;
    border-radius: 12px;
    background: var(--destructive-subtle);
    animation: caliper-fade-in var(--duration-fast) var(--ease-out);
  }
}

/* glide-highlight.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="glide-highlight"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: var(--radius-surface);
    background: var(--muted);
    opacity: 0;
    transition:
      transform var(--duration-travel) var(--ease-showcase),
      width var(--duration-travel) var(--ease-showcase),
      height var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="glide-highlight"][data-active="true"] {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="glide-highlight"] {
      transition: none;
    }
    [data-slot="glide-highlight"] {
      transition:
        transform 400ms var(--ease-showcase),
        width 400ms var(--ease-showcase),
        height 400ms var(--ease-showcase),
        opacity 280ms var(--ease-out);
    }
  }
}

/* split-button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="split-chevron"] {
    transition: rotate var(--duration-normal) var(--ease-settle);
  }
  [data-state="open"] > [data-slot="split-chevron"] {
    rotate: 180deg;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="split-chevron"] {
      transition: none;
    }
  }
}
